{noformat}function exp_raw(inputArray, startDateStr, endDateStr = null) {

  const startOfMonths = [];
  const startDate = new Date(startDateStr);
  const endDate = endDateStr ? new Date(endDateStr) : new Date(); // Use current date if endDateStr is not provided

  let currentDate = new Date(startDate);
  currentDate.setDate(1); // Set the date to the first day of the month

  while (currentDate <= endDate) {
    const firstDayOfMonth = new Date(currentDate.getFullYear(), currentDate.getMonth(), 1);
    startOfMonths.push(firstDayOfMonth.toISOString().slice(0, 10));;
    currentDate.setMonth(currentDate.getMonth() + 1);
  }

  cartesianProduct = []

  for (const date of startOfMonths) {
    for (const element of inputArray) {
      cartesianProduct.push([date, element[0]]); // Convert the date back to string format
    } 
  }

  return cartesianProduct
