{noformat}function getStartOfMonths(startDate) {
  const today = new Date();
  let currentDate = new Date(startDate);
  const startOfMonths = [];

  while (currentDate <= today) {
    const year = currentDate.getFullYear();
    const month = String(currentDate.getMonth() + 1).padStart(2, '0');
    const day = String(currentDate.getDate()).padStart(2, '0');
    startOfMonths.push(`${year}-${month}-${day}`);
    currentDate.setDate(currentDate.getDate() + 1);
  }

  return startOfMonths;
}

function populateAdsImpactForGeoMedium(datesList, geoMediumsList, impactsList) {
  // Create an object to store the start of months for each geoMedium
  const startOfMonthsDict = {};

  // Loop through the lists and find the earliest date for each geoMedium
  for (let i = 0; i < datesList.length; i++) {
    const date = new Date(datesList[i][0]);
    const geoMedium = geoMediumsList[i][0];

    // If the geoMedium is not in the startOfMonthsDict or the current date is later, update the date
    if (!(geoMedium in startOfMonthsDict) || date > startOfMonthsDict[geoMedium]) {
      startOfMonthsDict[geoMedium] = date;
    }
  }

  // Create a list to store the populated results
  const result = [];

  // Loop through the unique geoMediums
  for (const geoMedium in startOfMonthsDict) {
    const startDate = startOfMonthsDict[geoMedium];
    const startOfMonths = getStartOfMonths(startDate);

    // Populate the same result for each date after the experiment
    for (const date of startOfMonths) {
      result.push([geoMedium, date, impactsList[geoMediumsList.findIndex((item) => item[0] === geoMedium)][0]]);
    }
  }

  return result;
}{noformat}

