{noformat}function findClosestDate(rebudgetDate, expDatesList) {
  // Get the current date
  const currentDate = new Date();

  // Filter out dates that are after the current date and strictly before rebudgetDate
  const filteredDates = expDatesList.filter(date => new Date(date) < currentDate && new Date(date) < new Date(rebudgetDate));

  // Sort the filtered dates in ascending order
  filteredDates.sort((a, b) => new Date(b) - new Date(a));

  // Find the date closest to rebudgetDate
  let closestDate = null;
  let minDiff = Infinity;

  filteredDates.forEach(date => {
    const diff = Math.abs(new Date(date) - new Date(rebudgetDate));
    if (diff < minDiff) {
      minDiff = diff;
      closestDate = date;
    }
  });

  return closestDate;
}
{noformat}

