{noformat}function populateAdsImpactForGeoMedium(datesList, geoMediumsList, impactsList) {

  // setting next Month's date (not current month due to more convenient population algorithm)
  const todayDate = new Date();
  nextMonthDate = new Date(todayDate.getFullYear(), todayDate.getMonth()+1, 1);
  const nextMonthYear = nextMonthDate.getFullYear()
  const nextMonthMonth = String(nextMonthDate.getMonth()+1).padStart(2, '0');
  const firstDate = '01'
  const nextMonthDateString = `${nextMonthYear}-${nextMonthMonth}-${firstDate}`;
  console.log(nextMonthDateString)

  // Check if input lists have the same length
  if (datesList.length !== geoMediumsList.length || datesList.length !== impactsList.length) {
    throw new Error('Input lists must have the same length.');
  }

  const entities = [];

  geoMediumsList_u  = [... new Set(geoMediumsList.flat())]

  for (const geoMedium_1 of geoMediumsList_u) { 
  for (const [i, date] of datesList.entries()) {

    if  (geoMedium_1 == geoMediumsList[i][0]) {
    const date = datesList[i][0].toISOString().split('T')[0]; // Access the date value from the nested list
    const geoMedium = geoMediumsList[i][0];
    const impact = impactsList[i][0];

    entities.push([geoMedium, date, impact]);
    }
  }
  entities.push([geoMedium_1, nextMonthDateString, 0]) // Pushing with zero impact, because impact variable is not available (but we're setting it as next month)
  }

  //console.log(entities)

  entities.sort((a, b) => {
    if (a[0] !== b[0]) {
      return a[0].localeCompare(b[0]);
    } else {
      return a[1].localeCompare(b[1]);
    }
  });

  const populatedEntities = [];
  for (let i = 0; i < entities.length - 1; i++) {
    const currentEntity = entities[i];
    const nextEntity = entities[i + 1];
    populatedEntities.push(currentEntity);

    if (currentEntity[0] === nextEntity[0]) {
      const currentDate = new Date(currentEntity[1]);
      const nextDate = new Date(nextEntity[1]);

      const dateRange = getDateRange(currentDate, nextDate);
      const impact = currentEntity[2];

      for (let j = 1; j < dateRange.length - 1; j++) {

        var correct_tz_date = new Date(dateRange[j].getTime() - dateRange[j].getTimezoneOffset()*60000); // otherwise summer dates get minus one day
        date = (correct_tz_date).toISOString().split('T')[0];


        populatedEntities.push([currentEntity[0], date, impact]);
      }
    }
  }

  populatedEntities.push(entities[entities.length - 1]);

  return populatedEntities;
}

function getDateRange(start_date, end_date) {
  const startOfMonths = [];
  let currentMonth = new Date(start_date);
  currentMonth.setDate(1); // Set the day to the first day of the month

  while (currentMonth <= end_date) {
    startOfMonths.push(new Date(currentMonth));
    currentMonth.setMonth(currentMonth.getMonth() + 1);
    currentMonth.setDate(1); // Set the day back to the first day of the month
  }

  return startOfMonths;
}

